var a={en:`Orders gained direct access to the payment database and PSP, while Payments stopped consuming the broker. Payment status can diverge from order state.`,ua:`Orders отримав прямий доступ до БД платежів і PSP, а Payments перестав читати брокер. Стани оплати й замовлення можуть розійтися.`};var n={en:[`Remove Orders→paymentdb and Orders→psp shortcuts.`,`Restore broker→payments and an explicit result contract.`,`Explain charge reconciliation after request timeout.`],ua:[`Прибери Orders→paymentdb та Orders→psp.`,`Віднови broker→payments і явний контракт результату.`,`Поясни звірення оплати після таймауту запиту.`]};var r=[{en:`Only Payments owns its database and PSP adapter.`,ua:`Лише Payments володіє своєю БД й адаптером PSP.`},{en:`Payment events reach Payments through its designated contract.`,ua:`Події оплати надходять до Payments через визначений контракт.`}];var s={remove:[`broker->payments`],add:[{from:`orders`,to:`paymentdb`,kind:`data`,label:`Intentional defect / Навмисна помилка`},{from:`orders`,to:`psp`,kind:`sync`,label:`Intentional defect / Навмисна помилка`}]};var d={scenario:a,tasks:n,checks:r,mutations:s};export{r as checks,d as default,s as mutations,a as scenario,n as tasks};